class Box{n:i32=1;}
@tsfgValue class V{x:i32=1;child:Box=new Box();}
function change(p:V):i32{p.x=7;p.child.n=9;return p.x;}
function pass(p:V):V{return p;}
export function f():i32{const a=new V();const b=a;b.x=2;b.child.n=3;return a.x+a.child.n;}
export function g():i32{const a=new V();const n=change(a);const b=pass(a);b.x=5;return a.x+a.child.n+n;}
export function h():i32{const a=new V();const before=a.x;let b:V=new V();b=a;b.x=2;const early=b.x;b.x=4;return before+early+a.x;}
export function valueAt(a:V[],i:u32):V{return a[i];}
